import json, re
A=json.load(open('/workspace/bojxona/anchors2.json'))
UZ_DOC="https://lex.uz/uz/docs/2924955"; RU_DOC="https://lex.uz/docs/2924953"
def tr(s):
    m={'а':'a','б':'b','в':'v','г':'g','д':'d','е':'e','ё':'yo','ж':'j','з':'z','и':'i','й':'y','к':'k','л':'l','м':'m','н':'n','о':'o','п':'p','р':'r','с':'s','т':'t','у':'u','ф':'f','х':'x','ц':'ts','ч':'ch','ш':'sh','ъ':'ʼ','ь':'','э':'e','ю':'yu','я':'ya','ў':'oʻ','қ':'q','ғ':'gʻ','ҳ':'h'}
    out=''
    for i,ch in enumerate(s):
        lo=ch.lower()
        if lo in m:
            r=m[lo]
            if lo=='е' and (i==0 or not s[i-1].isalpha()): r='ye'
            if ch.isupper(): r=r.upper() if (i+1<len(s) and s[i+1].isupper()) else r[:1].upper()+r[1:]
            out+=r
        else: out+=ch
    return out
def names(g):
    iu,tu=A['uz'][g]; ir,trr=A['ru'][g]
    nu=re.findall(r'«([^»]+)»',tu); nr=re.findall(r'«([^»]+)»',trr)
    nu=' / '.join(x for x in nu if x!='С'); nr=' / '.join(x for x in nr if x!='С')
    return nu or None, nr or None, f"{UZ_DOC}#{iu}", f"{RU_DOC}#{ir}", tu.split(')')[0]
S=lambda *x: list(x)
G=[]
def add(g, level, fmt, rule, src, example=None, classifier=None, checks=None, notes=None, filled_by="declarant"):
    nu,nr,uu,ur,sub=names(g)
    G.append(dict(grafa=g.replace('«С»','C').replace('15а','15a'), name_uz_cyrl=nu, name_uz_latn=tr(nu) if nu else None, name_ru=nr,
      level=level, filled_by=filled_by, format=fmt, rule_en=rule, source_documents=src, classifier=classifier,
      example=example, cross_checks=checks or [], notes=notes,
      legal_source=dict(doc="Instruction on the procedure for filling in the cargo customs declaration (BYD/GTD), MoJ reg. No. 2773 of 06.04.2016", point=f"Ch.5, point 25, sub-point {sub}", url_uz=uu, url_ru=ur)))
add('1','header','3 subfields: [IM] [2-digit regime code] [empty]',"Subfield 1: direction 'ИМ'. Subfield 2: two-digit customs regime code per Annex 3 (release for free circulation = 40). Subfield 3 is not filled.",["calculated"],example="ИМ | 40 |",classifier="Annex 3 – customs regimes (40 = import)")
add('2','header','free text, separate e-GTD fields per party',"Person named as consignor in the transport document: for a legal entity – short name + location (country short name per Annex 5 + address); for an individual – full name + residence. If the consignor ships on behalf of another person: consignor first, then 'по поручению' + the person who contracted with the grafa-9 party. In the e-GTD each party goes into its own field. Optional consignor TIN after '№' only for simplified corridor / AEO mutual-recognition cases. Latin-script names stay in Latin (point 11).",["cmr","invoice","contract"],example="Foshan Mingde Furniture Co., Ltd. (SYNTHETIC), Китай, Guangdong, Foshan, Shunde, Longjiang Rd 88",checks=["CMR box 1 consignor = invoice seller (or 'on behalf of' chain explained)"],notes="Not filled on additional sheets of a paper GTD.")
add('3','header','"n/N" integers',"Sheet number / total sheets incl. main and additional. Paper: main sheet holds 1 item, each additional sheet holds 3 items (point 17), max 33 additional sheets. E-GTD: show the numbers as if printed. No additional sheets → '1/1'.",["calculated"],example="1/2 (2 items)",checks=["N = 1 + ceil((items-1)/3)"])
add('5','header','integer',"Total number of goods items = number of filled grafa 31 entries. Max 100 items per GTD (point 6).",["calculated"],example="2",checks=["= count(items)","<= 100"])
add('7','header','5-digit post code (declarant); customs appends /DD.MM.YYYY/serial',"Declarant enters the 5-digit code of the customs post where the GTD is filed (Annex 4). Customs (point 90) completes the registration number: 99999/DD.MM.YYYY/9999999.",["user_input"],example="26010 (declarant) → 26010/27.11.2026/0001234 (customs)",classifier="Annex 4 – customs posts",filled_by="declarant+customs")
add('8','header','free text + upper-right code after № + bottom: № TIN / district code',"Importer/consignee: legal entity – short name, legal address, phone, e-mail (if any); individual – full name, permanent address, phone. If consignee ≠ importer: consignee first, then 'по поручению' importer. If grafa 9 already shows the importer, the importer need not be repeated here. Upper-right after '№': 00000001 resident individual, 00000002 non-resident individual, 00000003 organisation with state share, 99999999 diplomatic missions, 88888888 international/governmental organisation offices; otherwise empty. Bottom after '№': consignee TIN (of the branch if a branch acts), '/', district (city) code per Annex 15; no TIN → 999999999.",["cmr","contract","company_profile"],example="«UYJIHOZ SAVDO» MChJ (SYNTHETIC), г. Ташкент, Чиланзарский р-н, ул. Бунёдкор 1, тел. +998 71 000 00 00 | № 123456789/1726294",classifier="Annex 15 – districts and cities",checks=["CMR box 2 consignee = importer (or chain explained)","TIN 9 digits","district code exists in Annex 15"],notes="Not filled on additional sheets of a paper GTD.")
add('9','header','free text + upper code + bottom: № TIN/PINFL / district code',"Person who concluded the foreign-trade contract and is responsible for settlements: name, legal address, phone, e-mail (legal entity) or full name, residence, phone (individual). Upper '№' codes as in grafa 8 (00000001/00000002/00000003/99999999/88888888 or empty). Bottom: TIN (PINFL for an individual) / district code (Annex 15); none → 999999999. Not filled for gratuitous supplies.",["contract","company_profile"],example="«UYJIHOZ SAVDO» MChJ ... | № 123456789/1726294",checks=["= buyer in contract","= buyer in invoice (Annex 1a item 2)"])
add('11','header','left: 3-digit country code; right: 1 or 2',"Left: numeric code (Annex 5) of the country where the counterparty that signed the contract with the grafa-9 person is registered/resides. If no contract – per accompanying documents. Right: '1' if that country/territory is on the offshore list approved by MoJ reg. No. 2467 of 12.06.2013, otherwise '2'.",["contract"],example="156 | 2",classifier="Annex 5 – countries; offshore list reg. No. 2467",checks=["seller country in contract = code"],notes="Offshore list must be loaded as a separate reference table (not in this file).")
add('12','header','decimal(2), currency of grafa 22',"Total customs value = sum of grafa 45 of all items, in the grafa-22 currency.",["calculated"],checks=["= Σ grafa 45 (exact)"])
add('13','header','decimal: UZS per 1 USD',"US dollar rate to UZS set by the Central Bank on the date the GTD is accepted for clearance.",["cbu_rate"],notes="Rate date = acceptance date, which the product cannot know in advance → recompute at filing (Customs Code Art. 326).")
add('14','header','free text + upper: № TIN/PINFL',"Customs broker or declarant (legal entity) that filled in and files the GTD: short name, legal address, phone, e-mail; individual declarant: full name, address, phone, e-mail. Upper '№': TIN (PINFL for an individual). For YuklaGo self-filing this is the importer itself.",["company_profile"],example="«UYJIHOZ SAVDO» MChJ ... | № 123456789")
add('15','header','country short name (Annex 5)',"Country of dispatch: country from which goods were sent to Uzbekistan without commercial deals or other operations in intermediate countries changing their legal status; determined from the transport document that started the international carriage. Several transport documents → first country where the goods were taken over for carriage to the grafa-8 consignee.",["cmr"],example="КИТАЙ",checks=["CMR box 4 (place of taking over) country"])
add('15а','header','3-digit numeric (Annex 5)',"Numeric code of the dispatch country.",["calculated"],example="156",classifier="Annex 5")
add('18','header','left: "<count> <TRANSPORT>: plate[/trailer]; ..."; right: country code',"Vehicle that carried the goods inside Uzbekistan to the clearing post. Left: number of vehicles, space, short transport name per Annex 6 (e.g. АВТО), colon, vehicle identifiers separated by ';' with trailers after '/'. Right: numeric code of the country of registration of the tractor unit; several countries → '999' (e-GTD lists all in fields, no 'see reverse').",["cmr","transit_declaration"],example="1 АВТО: 01A123BC/01XY456 | 860",classifier="Annex 6 – transport types",checks=["plates = CMR box 25 / transit declaration"])
add('19','header','0 or 1',"'0' – not in a container; '1' – in a container or the container itself is declared as goods.",["cmr","packing_list"],example="0")
add('20','header','sub1: 2-digit code; sub2: Incoterms letters + place; sub3: payment-form code "/" dispatch-form code',"Delivery terms from the contract. Sub1 numeric code and sub2 letter code + geographic point per Annex 7. Sub3: payment form 10 prepayment, 20 letter of credit, 30 bank guarantee, 40 collection, 50 upon import, 60 consignment, 70 barter, 80 gratuitous (mixed → the one with the largest share); then '/' dispatch form 01 shipped directly by the contracting party, 02 not directly. E-GTD: each code in its own field.",["contract","invoice"],example="02 | FCA Foshan | 10/01",classifier="Annex 7 – delivery terms (01 EXW, 02 FCA, 03 FAS, 04 FOB, 05 CFR, 06 CIF, 07 CPT, 08 CIP, 09 DAF, 10 DES, 11 DEQ, 12 DDU, 13 DDP, 14 DAP, 15 DAT, 99 other)",checks=["invoice Incoterms = contract Incoterms","payment terms in contract → code"],notes="⚠️ Annex 7 has no DPU (Incoterms 2020) – likely '99' + letters; VMQ 605 Annex 1a still says 'Incoterms-2010'. Open question.")
add('21','header','same as grafa 18 + country code',"Vehicle(s) on which the goods actually crossed the Uzbek customs border; same format as grafa 18; right: country code of the tractor unit's registration; several countries → '999'. Not filled if the goods have not crossed the border before (change of regime).",["cmr","transit_declaration"],example="1 АВТО: 01A123BC/01XY456 | 860",checks=["= CMR vehicle; = border-post stamp"])
add('22','header','left: 3-digit currency code; right: decimal(2)',"Left: numeric code (Annex 8) of the contract currency (currency in which goods are priced). Right: total invoice value of the consignment = Σ grafa 42.",["contract","invoice"],example="840 | 12100.00",classifier="Annex 8 – currencies (840 USD, 156 CNY, 949 TRY, 860 UZS)",checks=["= Σ grafa 42 (exact)","= invoice total","currency = contract currency"])
add('23','header','"<nominal>/<rate>" with comma decimals',"CBU rate of the grafa-22 currency to UZS on the date of GTD acceptance, written as nominal/rate, e.g. '1/63,41', '10/220,09'; UZS contract → '1/1'.",["cbu_rate"],example="1/12100,00 (EXAMPLE rate)")
add('24','header','left: transaction-nature code; right: 3-digit settlement currency',"Left: transaction nature code per Annex 9 (01 = ordinary trade with settlement in national or foreign currency). Right: numeric code of the currency in which the grafa-9 party settles with the counterparty.",["contract"],example="01 | 840",classifier="Annex 9 – nature of transaction")
add('25','header','2-digit code',"Transport type code (Annex 6) of the grafa-21 vehicle. Not filled if goods did not cross the border before.",["calculated"],example="30",classifier="Annex 6 (10 sea, 20 rail, 30 road, 40 air, 71 pipeline, 72 power line, 80 river, 90 self-propelled)")
add('26','header','2-digit code',"Transport type code (Annex 6) of the grafa-18 vehicle.",["calculated"],example="30",classifier="Annex 6")
add('28','header','TIN/PINFL',"TIN (PINFL for an individual) of the payer of customs payments; if a non-resident pays – TIN/PINFL of the broker or declarant.",["company_profile"],example="123456789")
add('29','header','5-digit code + name',"Code and name (Annex 4) of the customs post through which the goods entered Uzbekistan. Not filled if goods did not cross the border before.",["transit_declaration","cmr"],example="03002 Дустлик",classifier="Annex 4",checks=["= border post stamp on CMR / transit declaration"])
add('30','header','text + (e-GTD) district code',"Location of goods at filing: customs or free warehouse / duty-free shop → number and date of its licence; place without customs-warehouse status → postal address (no postcode); railway station → its name. E-GTD: separate field with district (city) code per Annex 15.",["transit_declaration","user_input"],example="г. Ташкент, Сергелийский р-н, ... (SYNTHETIC) | 1726283",classifier="Annex 15")
add('31','item','numbered lines 1–11 + bottom-left consumer TIN/district + bottom-right supplementary quantity',"Description sufficient for unambiguous 10-digit classification. Line 1: trade name, trademark/brand, model, article, grade, standards, technical and commercial characteristics, quantitative and qualitative composition; energy-efficiency class for appliances listed in the annex to CM Resolution No. 86 of 09.04.2015; e-GTD: brand in separate field ('без марки'/'без бренда' if none); parameters in other units and production date when needed for payments or measures. Using only the TN VED heading text is NOT allowed. Line 2: number of packages, packaging type and number of packings ('часть коробки' if partial; bulk codes 01 насыпью/02 навалом/03 наливом). Line 3: container numbers ('часть' if partial). Line 4: excise stamps. Line 5: pipeline/power-line supply period. Line 6: aggregated import code (separate table). Line 7: shelf life for food and medicines. Line 8: investment-project codes (101/102/103/201/202/203 and further codes in the text). Line 9: 3-digit technological-equipment sphere code (Annex 16) for listed HS headings, '000' if sphere not listed. Line 10: year of manufacture / technical parameters of such equipment. Line 11: '01' state procurement / '02' not state procurement. Bottom-left: TIN/PINFL of the end consumer + '/' district code (unknown or several → consignee). Bottom-right: quantity in supplementary unit, 2 decimals (6 if < 0.01); e-GTD: number only; not filled if only 'kg'.",["invoice","packing_list","cmr","contract","classification"],example="1) Стол обеденный из массива гевеи, модель DT-1600, 1600x900x750 мм, бренд MINGDE ...\n2) 80 мест, картонные коробки\n... | 123456789/1726294 | 40,00",classifier="Annex 15, Annex 16",checks=["packages (line 2) = CMR box 6-7 = packing list = invoice","supp. quantity = invoice qty = packing list qty","description not equal to bare heading text","brand present or 'без бренда'"],notes="One item = same name, type, brand, one 10-digit code, one origin, same tariff treatment (point 7). Consumer goods with the same code but different names/brands/models/specs must be separate items (point 8). For smartphones: IMEI required in grafa 31 per tariff team note (VM 778) – out of demo scope.")
add('32','item','integer',"Sequential number of the item declared in grafa 31; single item → '1'.",["calculated"],example="1")
add('33','item','10 digits, no spaces',"10-digit TN VED (TIF TN) code of the grafa-31 goods, written without spaces or separators (left part).",["classification","invoice"],example="9403601000",checks=["code exists and active in PQ-181 Annex 1 list","first 6 digits vs invoice HS (Annex 1a item 3) – warn on mismatch"],notes="Right part of grafa 33 is not described in point 25 for IM40 – leave empty unless the cabinet requires it ⚠️.")
add('34','item','3-digit numeric (or "EU", "000")',"Left: numeric origin-country code (Annex 5). Unknown at clearance → '000'. Certificate naming only the European Union → 'EU' (Latin).",["certificate_of_origin","invoice"],example="156",classifier="Annex 5",checks=["= certificate of origin country","= invoice origin (Annex 1a item 4)"],notes="Origin drives the Art. 300¹ surcharge for non-MFN/unknown origin (see data/tariff).")
add('35','item','decimal(3) kg',"Gross mass in kg of the grafa-31 goods: total mass incl. all packaging needed to keep goods intact until they enter circulation, EXCLUDING containers and other transport equipment. Round mathematically to 3 decimals (<1 g → 6 decimals).",["packing_list","cmr"],example="1760.000",checks=["Σ grafa 35 vs CMR gross (box 11)","Σ grafa 35 = packing list gross","gross ≥ net"],notes="Whether pallets count as packaging or transport equipment is not stated ⚠️.")
add('37','item','7 digits',"Procedure code = declared regime (2) + previous regime (2; '00' if none or only customs transit) + movement-feature code (3) per Annex 11 ('000' = feature not established).",["calculated"],example="4000000",classifier="Annex 3, Annex 11")
add('38','item','decimal(3) kg',"Net mass in kg: without any packaging, except primary packaging in which goods are sold at retail and/or which cannot be separated before use without loss of consumer properties (e.g. coffee in a can). Bulk goods → total mass. Round to 3 decimals.",["packing_list","invoice"],example="1520.000",checks=["net ≤ gross","= packing list net","= invoice net (Annex 1a item 8)"])
add('39','item','quantity + unit',"Only for goods under quantitative restrictions: remaining quota per licence, not counting the goods now declared.",["license"],example="(empty for demo goods)")
add('40','item','"<doc code> post/date/number — item — gross kg — net kg — supp qty"',"Previous document. Previous GTD: 'ГТД post/date/number — item — gross — net — supp qty'. Customs transit: 'ТД 06010/01.03.2022/0003761 — 3 — 7980 кг — 7900 кг — 350,2 м3'. No GTD/TD but delivery-control document: 'ККДГ post/date/ИМnumber — gross' (Cyrillic letters) or 'МДП post/date/XYnumber — gross' (Latin letters). Several previous documents → one per line. Vehicle imported under return obligation → 'МB …'.",["transit_declaration"],example="ТД 03002/10.11.2026/0012345 — 1 — 1760 кг — 1520 кг — 40 шт (SYNTHETIC)",checks=["TD weights vs GTD weights"],notes="For a truck cleared at an inland post the transit declaration is normally the previous document (Customs Code Art. 261 part 3).")
add('41','item','unit code',"Code of the supplementary unit (TN VED 'table of units') for the quantity in grafa 31 bottom-right; empty if only kg applies.",["classification"],example="796 (шт) ⚠️ verify code",notes="Supplementary unit per code is in data/tariff/tiftn_codes_pq181_annex1.csv; the numeric unit code table is not in this file ⚠️.")
add('42','item','decimal(2), contract currency',"Invoice value of the item actually paid or payable (or compensated by counter-deliveries) per the contract, in contract currency; gratuitous/no contract → per accompanying documents. Round to 2 decimals.",["invoice"],example="5800.00",checks=["= Σ invoice lines for this item","Σ = grafa 22"])
add('43','item','0 or 1',"'0' – consignee imports goods NOT for its own needs; '1' – for its own needs.",["user_input"],example="0")
add('44','item','one document per line: "<code> <short> № ... от DD.MM.YYYY"',"Documents supporting each item, each with ordinal code and letter code per Annex 12: licence (101 ЛИЦЕНЗИЯ … срок), transport & commercial docs (202 СМР, 220 ИНВ, 221 ИНВПРФ, 222 УПЛИСТ, 223 ИНВ_ОТ …), contract (301 КНТ), supplementary agreement (302 ДОП), contract specification (307 SPES_N), transport contract with non-resident carrier (305 КНТ_ТР) and its e-system ID (306 IDN_ТР), permits & certificates (e.g. 417 ССТ conformity certificate, 441 MTD declaration of conformity), contract registration (501…), benefits ('6' + payment code + Annex 14 act code, e.g. '629 15-142120030000'), certificate of origin (701 СПТИМ), other docs (deferral, commission contract, fine decision, foreign export declaration …). Customs adds its own entries (inspection act etc., point 90).",["contract","invoice","cmr","packing_list","certificate_of_origin","conformity_certificate"],example="202 СМР № CN-UZ-77812 от 01.11.2026\n220 ИНВ № MD-2026-118 от 28.10.2026\n222 УПЛИСТ № MD-PL-118 от 28.10.2026\n301 КНТ № 15/2026 от 05.09.2026\n701 СПТИМ № 26C4400A0123 от 30.10.2026",classifier="Annex 12 – document types; Annex 14 – benefit acts",filled_by="declarant+customs",checks=["every doc referenced exists in the pack","dates: contract ≤ invoice ≤ CMR","certificate valid on filing date"])
add('45','item','decimal(2), contract currency (right subfield)',"Right subfield: customs value of the item in contract currency (gratuitous/no contract → currency of accompanying documents), determined by the Customs Code valuation methods (Arts. 302–313). Round to 2 decimals.",["calculated","invoice","freight_invoice"],example="7761.14",checks=["≥ invoice value when Incoterms leave freight to the border unpaid (Art. 304)","Σ = grafa 12"],notes="Left subfield content is not described for IM40 in point 25 ⚠️ (cabinet may require valuation-method code).")
add('46','item','decimal(3), thousand USD',"Statistical value in thousand USD: grafa-42 invoice value brought to 'CIP (CIF) – border of Uzbekistan' terms, converted at CBU rate on acceptance date; 3 decimals.",["calculated"],example="7.761")
add('47','item','table rows: Вид | Основа начисления | Ставка | Сумма | СП',"Per item and per payment type. 'Вид' = payment code (Annex 13: 10 clearance fee, 20 import duty, 21 additional duty, 27 import excise, 29 VAT …). 'Основа' in UZS (conversion of grafa 12/45 at CBU rate on acceptance date) unless law sets a foreign-currency or non-money base (then quantity + unit). 'Ставка' = applied rate. 'Сумма' in UZS. 'СП' method: БН bank transfer, КТ cash, УН conditional accrual, ОП deferral, РП instalments, ПП per-batch under periodic GTD, ВЗ VAT offset, ОО not payable. Clearance fees always shown only once (e-GTD: under item No. 1). No row when rate not set / zero or no obligation under the regime.",["calculated"],example="20 | 93909794.00 | 15% | 14086469.10 | БН",classifier="Annex 13 – customs payments",filled_by="declarant+customs",notes="Customs adds fees for clearance outside working hours/places (point 90). Rounding of UZS amounts is not stated in the instruction ⚠️.")
add('48','item','"XX.DD.MM.YYYY" or "ПН.XX.DD.MM.YYYY.SUM"',"Only when deferral/instalments granted: per payment type the deadline 'XX.DD.MM.YYYY' (XX = payment code); instalments 'ПН.XX.DD.MM.YYYY.SUM' one per line.",["customs_decision"],example="(empty for demo)")
add('49','item','licence number and date',"Number and date of the customs/free warehouse licence if the goods were previously placed under a regime involving storage there; otherwise not filled.",["user_input"],example="(empty)")
add('50','header','fixed sentence + full name, position, phone, PINFL (+ power of attorney)',"Text: 'Ответственность за представленные документы и сведения несет …' + full name, position, phone, PINFL (separate e-GTD field) of the person responsible – the declarant or its authorised person. Non-resident without PINFL → 14 nines. If an authorised person: number, date and validity of the contract/power of attorney.",["company_profile","user_input"],example="Ответственность ... несет Каримов Азиз Бахромович, директор, +998 90 000 00 00 | ПИНФЛ 12345678901234 (SYNTHETIC)")
add('54','header','numbered lines 1–5; GTD own number PINFL/DD.MM.YYYY/serial',"Declaring person filing on behalf of the grafa-14 person: 1 place of filling; 2 full name + e-mail; 3 phone; 4 (broker only) number/date of broker–client contract; 5 declarant's own GTD number '99999999999999/99.99.9999/999999' = PINFL / filling date / serial number increasing within the year (restarts each year, never repeated). E-GTD authenticity is certified by the declaring person's ЭЦП (ERI).",["company_profile","calculated"],example="1) г. Ташкент\n2) Каримов Азиз Бахромович, info@example.uz\n3) +998 90 000 00 00\n5) 12345678901234/26.11.2026/000017",checks=["serial unique within year"],notes="'Declaring person' = declarant filing itself or a customs-clearance specialist employed by the declarant/broker (point 1).")
add('«С»','header','numbered lines 1–2',"1: identification number of the foreign-trade contract in the Unified Electronic Information System of Foreign Trade Operations; 2: date of import into Uzbekistan = date of the stamp of the border post on the accompanying documents, or date of registration of the delivery-control book / TIR carnet at the border post.",["contract","cmr","transit_declaration"],example="1) 2026-UZ-000123456 (SYNTHETIC ID)\n2) 10.11.2026",checks=["contract registered in the e-system (ID present)","date of import ≤ filing date"])
